class Solution:
    def canFinish(self, n, prerequisites):
        graph=[[] for _ in range(n)]; degree=[0]*n
        for course, prereq in prerequisites: graph[prereq].append(course); degree[course]+=1
        queue=[i for i in range(n) if degree[i]==0]; done=0
        for node in queue:
            done+=1
            for nxt in graph[node]:
                degree[nxt]-=1
                if degree[nxt]==0: queue.append(nxt)
        return done==n
